// AccountServiceServer is the server API for AccountService service.
// All implementations must embed UnimplementedAccountServiceServer
// for forward compatibility.
type AccountServiceServer interface {
	SignUp(context.Context, *SignUpRequest) (*SignUpResponse, error)
	SignIn(context.Context, *SignInRequest) (*SignInResponse, error)
	SignOut(context.Context, *SignOutRequest) (*v1.Empty, error)
	RefreshToken(context.Context, *RefreshTokenRequest) (*RefreshTokenResponse, error)
	Me(context.Context, *MeRequest) (*Account, error)
	UpdateAccount(context.Context, *UpdateAccountRequest) (*Account, error)
	// 注销当前登录账号（T-03）：匿名化软删——凭据立即失效（全部会话撤销 +
	// 状态置 deleted，每次鉴权实时校验），email/name/手机号/凭据哈希就地
	// 清洗，同邮箱可立即重新注册（不泄露"曾存在"）；其名下文档/文件/审计
	// 行保留为孤儿数据（显式决策，不做级联删除）。
	DeleteAccount(context.Context, *DeleteAccountRequest) (*v1.Empty, error)
	// 确认邮箱变更：消费邮件中的一次性 secret，验证通过后 email 才切换
	// （staging：验证前 email 保持旧值，旧邮箱仍可登录/找回）。
	// ACCESS_PUBLIC：邮件链接点开即完成（与 recovery 同一安全模型——256-bit
	// 随机 secret + 24h TTL + GETDEL 一次性消费），点链接无需登录态。
	ConfirmEmailChange(context.Context, *ConfirmEmailChangeRequest) (*Account, error)
	ListSessions(context.Context, *ListSessionsRequest) (*ListSessionsResponse, error)
	DeleteSession(context.Context, *DeleteSessionRequest) (*v1.Empty, error)
	DeleteSessions(context.Context, *DeleteSessionsRequest) (*v1.Empty, error)
	GetPrefs(context.Context, *GetPrefsRequest) (*GetPrefsResponse, error)
	UpdatePrefs(context.Context, *UpdatePrefsRequest) (*GetPrefsResponse, error)
	CreateEmailOTP(context.Context, *CreateEmailOTPRequest) (*ChallengeResponse, error)
	CreateEmailOTPSession(context.Context, *CreateEmailOTPSessionRequest) (*SignInResponse, error)
	CreateOAuth2Session(context.Context, *CreateOAuth2SessionRequest) (*CreateOAuth2SessionResponse, error)
	CreateOAuth2TokenSession(context.Context, *CreateOAuth2TokenSessionRequest) (*SignInResponse, error)
	CreatePhoneOTP(context.Context, *CreatePhoneOTPRequest) (*ChallengeResponse, error)
	CreatePhoneOTPSession(context.Context, *CreatePhoneOTPSessionRequest) (*SignInResponse, error)
	CreateWeChatMiniProgramSession(context.Context, *CreateWeChatMiniProgramSessionRequest) (*SignInResponse, error)
	CreateAnonymousSession(context.Context, *CreateAnonymousSessionRequest) (*SignInResponse, error)
	CreateOAuth2LinkSession(context.Context, *CreateOAuth2LinkSessionRequest) (*CreateOAuth2SessionResponse, error)
	CreateOAuth2LinkTokenSession(context.Context, *CreateOAuth2LinkTokenSessionRequest) (*Account, error)
	CreateVerification(context.Context, *CreateVerificationRequest) (*CreateVerificationResponse, error)
	UpdateVerification(context.Context, *UpdateVerificationRequest) (*Account, error)
	CreateRecovery(context.Context, *CreateRecoveryRequest) (*v1.Empty, error)
	UpdateRecovery(context.Context, *UpdateRecoveryRequest) (*v1.Empty, error)
	// MFA
	ListFactors(context.Context, *ListFactorsRequest) (*ListFactorsResponse, error)
	CreateTOTPFactor(context.Context, *CreateTOTPFactorRequest) (*TOTPFactor, error)
	VerifyTOTPFactor(context.Context, *VerifyTOTPFactorRequest) (*Factor, error)
	DeleteFactor(context.Context, *DeleteFactorRequest) (*v1.Empty, error)
	CreateMFASession(context.Context, *CreateMFASessionRequest) (*SignInResponse, error)
	// 一次性 JWT
	CreateJWT(context.Context, *CreateJWTRequest) (*CreateJWTResponse, error)
	// Magic URL
	CreateMagicURLSession(context.Context, *CreateMagicURLSessionRequest) (*ChallengeResponse, error)
	UpdateMagicURLSession(context.Context, *UpdateMagicURLSessionRequest) (*SignInResponse, error)
	// 账号日志
	ListLogs(context.Context, *ListLogsRequest) (*ListLogsResponse, error)
	mustEmbedUnimplementedAccountServiceServer()
}

